# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
import pytest
import torch

import flag_gems

from . import accuracy_utils as utils

# Shapes covering 0D, 1D, 2D, 3D, 4D and zero-sized operands. transpose_ is a
# pure metadata mutation, so the degenerate ranks matter as much as the large
# ones: 0D/1D must stay untouched while >=2D must swap sizes and strides.
TRANSPOSE_SHAPES = [
    (),
    (5,),
    (2, 3),
    (128, 256),
    (2, 3, 4),
    (16, 128, 64),
    (2, 3, 4, 5),
    (8, 16, 32, 64),
    (0, 3, 4),
]

# Dimension pairs covering first/last, middle, negative and identity swaps.
TRANSPOSE_DIM_PAIRS = [
    (0, 0),
    (0, 1),
    (0, -1),
    (-1, -2),
    (1, 2),
    (1, -1),
]


def _wrapped_dims(ndim, dim0, dim1):
    """Wrap negative dims the way aten does (0D wraps against ndim=1)."""
    wrap = ndim if ndim > 0 else 1
    d0 = dim0 + wrap if dim0 < 0 else dim0
    d1 = dim1 + wrap if dim1 < 0 else dim1
    return wrap, d0, d1


def _assert_metadata_equal(res, ref):
    """transpose_ only rewrites metadata, so compare it explicitly."""
    assert res.shape == ref.shape
    assert res.stride() == ref.stride()
    assert res.storage_offset() == ref.storage_offset()


@pytest.mark.transpose_
@pytest.mark.parametrize("shape", TRANSPOSE_SHAPES)
@pytest.mark.parametrize("dim_pair", TRANSPOSE_DIM_PAIRS)
@pytest.mark.parametrize("dtype", utils.FLOAT_DTYPES)
def test_transpose_(shape, dim_pair, dtype):
    dim0, dim1 = dim_pair
    inp = torch.randn(shape, dtype=dtype, device=flag_gems.device)

    ndim = inp.dim()
    wrap, d0, d1 = _wrapped_dims(ndim, dim0, dim1)
    # Low-rank operands reject most of the pairs above, in both directions:
    # (1, -1) overflows a 1D tensor and (-1, -2) underflows it.
    if not (0 <= d0 < wrap and 0 <= d1 < wrap):
        pytest.skip(f"dim pair {dim_pair} out of range for {ndim}D tensor")

    # transpose_ mutates its operand and is not idempotent, so the reference
    # needs its own copy: on device (`--ref` unset) to_reference hands back the
    # very same tensor, and transposing it twice would compare a tensor to
    # itself.
    ref_inp = utils.to_reference(inp.clone())

    ref_out = torch.ops.aten.transpose_(ref_inp, dim0, dim1)
    res_out = flag_gems.transpose_(inp, dim0, dim1)

    utils.gems_assert_equal(res_out, ref_out)
    _assert_metadata_equal(res_out, ref_out)
    # The operand itself must carry the new metadata, and the op returns it.
    assert res_out is inp
    _assert_metadata_equal(inp, ref_inp)


@pytest.mark.transpose_
@pytest.mark.parametrize("shape", [(2, 3, 4), (8, 16, 32, 64)])
@pytest.mark.parametrize("dtype", utils.FLOAT_DTYPES)
def test_transpose__non_contiguous(shape, dtype):
    # A sliced operand keeps a non-trivial stride and a non-zero storage
    # offset; both must survive the in-place metadata rewrite. The slice is
    # built on each device separately because to_reference on a CPU reference
    # would densify the copy and make the stride comparison meaningless.
    base = torch.randn(shape, dtype=dtype, device=flag_gems.device)
    inp = base[::2]
    ref_base = utils.to_reference(base.clone())
    ref_inp = ref_base[::2]

    ref_out = torch.ops.aten.transpose_(ref_inp, 0, -1)
    res_out = flag_gems.transpose_(inp, 0, -1)

    utils.gems_assert_equal(res_out, ref_out)
    _assert_metadata_equal(res_out, ref_out)
    assert not res_out.is_contiguous()


@pytest.mark.transpose_
@pytest.mark.parametrize("dtype", utils.FLOAT_DTYPES)
def test_transpose__permuted(dtype):
    # Swapping dims of an already permuted operand must compose, not reset.
    # The leading slice also pushes the storage offset off zero (a `::2` slice
    # keeps it at 0), so the offset is checked against a non-trivial value.
    base = torch.randn((6, 4, 5), dtype=dtype, device=flag_gems.device)
    inp = base[2:].permute(2, 0, 1)
    ref_inp = utils.to_reference(base.clone())[2:].permute(2, 0, 1)
    assert inp.storage_offset() != 0

    ref_out = torch.ops.aten.transpose_(ref_inp, 0, 2)
    res_out = flag_gems.transpose_(inp, 0, 2)

    utils.gems_assert_equal(res_out, ref_out)
    _assert_metadata_equal(res_out, ref_out)


@pytest.mark.transpose_
@pytest.mark.parametrize("shape,dim0,dim1", [((2, 3, 4), 1, 1), ((5, 5), 0, 0)])
@pytest.mark.parametrize("dtype", utils.FLOAT_DTYPES)
def test_transpose__same_dim(shape, dim0, dim1, dtype):
    # Swapping a dimension with itself must leave sizes and strides untouched.
    inp = torch.randn(shape, dtype=dtype, device=flag_gems.device)
    ref_inp = utils.to_reference(inp.clone())
    before_shape, before_stride = inp.shape, inp.stride()

    ref_out = torch.ops.aten.transpose_(ref_inp, dim0, dim1)
    res_out = flag_gems.transpose_(inp, dim0, dim1)

    utils.gems_assert_equal(res_out, ref_out)
    _assert_metadata_equal(res_out, ref_out)
    assert res_out.shape == before_shape
    assert res_out.stride() == before_stride


@pytest.mark.transpose_
@pytest.mark.parametrize("dtype", utils.INT_DTYPES + utils.BOOL_TYPES)
def test_transpose__int_and_bool(dtype):
    # The op moves no payload, so every dtype goes down the same path.
    inp = torch.ones((16, 32), dtype=dtype, device=flag_gems.device)
    ref_inp = utils.to_reference(inp.clone())

    ref_out = torch.ops.aten.transpose_(ref_inp, 0, 1)
    res_out = flag_gems.transpose_(inp, 0, 1)

    utils.gems_assert_equal(res_out, ref_out)
    _assert_metadata_equal(res_out, ref_out)


